          if(version.snapshot){const values=version.snapshot.summary||{},facts=[['created',values.leadsCreated],['touched',values.leadsTouched],['outcomes',values.outcomes],['notes',values.notes],['followUpsRequired',values.followUpsRequired],['followUpsDue',values.followUpsDue],['overdue',values.followUpsOverdue]].filter(([,value])=>value!==undefined);const finance=version.snapshot.finance;if(finance)facts.push(['billed',formatQarMinor(finance.billedMinor)],['cash received',formatQarMinor(finance.cashReceivedMinor)],['credits issued',formatQarMinor(finance.creditsIssuedMinor)],['outstanding at run',formatQarMinor(finance.allOutstandingMinor)],['netCollections',formatQarMinor(finance.netCollectionsMinor)]);const list=document.createElement('ul');for(const [key,value] of facts){const item=document.createElement('li');item.textContent=`${t(key)}: ${value}`;list.appendChild(item);}article.appendChild(list);}
